dtsPropsFor.Button:
/** The look: `primary` for the screen's main action, `secondary` or `outline` beside it, `transparent` in toolbars and rows, `danger` for what deletes. Defaults to `primary` */
variant?: 'primary' | 'secondary' | 'outline' | 'transparent' | 'danger';
/** 32px, 40px or 48px tall. Defaults to `md` */
size?: 'sm' | 'md' | 'lg';
/** An icon from `Icons`, sized to the text. With no children the button becomes a square icon button: give it an `aria-label` */
icon?: React.ReactNode;
/** Which side of the label the icon sits on. Defaults to `start` */
iconPosition?: 'start' | 'end';
/** Asks twice. The first click swaps the label for this string, or for `'Confirm?'` when `true`, and only the second calls `onClick` */
confirm?: boolean | string;
/** How long an armed button waits for its second click before it reverts, in milliseconds. Defaults to 3000 */
confirmTimeout?: number;
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
/** Defaults to `button`, so a button in a form submits it only with `submit` */
type?: 'button' | 'submit' | 'reset';
disabled?: boolean;
/** Required on an icon-only button */
'aria-label'?: string;
children?: React.ReactNode;
className?: string;
style?: React.CSSProperties;
ref?: React.Ref<HTMLButtonElement>;
/** Every other attribute of a `<button>` passes through to it */

dtsPropsFor.Checkbox:
